class Solution
{
public:
    TreeNode*upsideDownBinaryTree(TreeNode*root)
    {
        TreeNode*parent = nullptr,*right = nullptr;
        while (root)
        {
            TreeNode*next = root->left;
            root->left = right;
            right = root->right;
            root->right = parent;
            parent = root;
            root = next;
        }
        return parent;
    }
};
